import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// In-process fake of the downstream pricing service (unit price in euros per sku).
const prices = { widget: 40, cheap: 0.5, ten: 10, hundred: 100, odd: 101 }
const pricing = { async priceOf(sku) { return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: raw ?? JSON.stringify(body) })
const json = async (res) => ({ status: res.status, type: res.headers.get('content-type'), body: await res.json() })

test('POST /orders creates an order, 201, string id, items echoed', async () => {
  const r = await json(await post({ items: [{ sku: 'ten', qty: 2 }] }))
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(Object.keys(r.body).sort(), ['id', 'items', 'total'])
  assert.equal(typeof r.body.id, 'string')
  assert.deepEqual(r.body.items, [{ sku: 'ten', qty: 2 }])
  assert.equal(r.body.total, 20)
})

test('POST /orders ids are sequential across orders', async () => {
  const a = await json(await post({ items: [{ sku: 'ten', qty: 1 }] }))
  const b = await json(await post({ items: [{ sku: 'ten', qty: 1 }] }))
  assert.equal(Number(b.body.id), Number(a.body.id) + 1)
})

test('POST /orders total is exactly 100: no discount', async () => {
  const r = await json(await post({ items: [{ sku: 'hundred', qty: 1 }] }))
  assert.equal(r.body.total, 100)
})

test('POST /orders total above 100 gets 10% discount, floored', async () => {
  assert.equal((await json(await post({ items: [{ sku: 'widget', qty: 3 }] }))).body.total, 108)
  assert.equal((await json(await post({ items: [{ sku: 'odd', qty: 1 }] }))).body.total, 90) // 90.9 floored
})

test('POST /orders total is floored to whole euros', async () => {
  assert.equal((await json(await post({ items: [{ sku: 'cheap', qty: 3 }] }))).body.total, 1)
})

test('POST /orders sums several items', async () => {
  const r = await json(await post({ items: [{ sku: 'ten', qty: 1 }, { sku: 'widget', qty: 1 }] }))
  assert.equal(r.body.total, 50)
})

test('POST /orders with missing qty returns 201 with total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no qty validation; NaN total serialises as null.
  const r = await json(await post({ items: [{ sku: 'ten' }] }))
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

test('POST /orders 400 when items missing, empty, not an array, or JSON invalid', async () => {
  for (const req of [post({}), post({ items: [] }), post({ items: 'x' }), post(null, '{not json')]) {
    const r = await json(await req)
    assert.equal(r.status, 400)
    assert.deepEqual(r.body, { error: 'items required' })
  }
})

test('POST /orders with empty body is 400', async () => {
  const r = await json(await post(null, ''))
  assert.equal(r.status, 400)
})

test('GET /orders/:id returns the stored order', async () => {
  const created = (await json(await post({ items: [{ sku: 'widget', qty: 3 }] }))).body
  const r = await json(await fetch(`${base}/orders/${created.id}`))
  assert.equal(r.status, 200)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.body, created)
})

test('GET /orders/:id unknown id returns 200 with error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — a missing order answers 200, not 404.
  const r = await json(await fetch(`${base}/orders/does-not-exist`))
  assert.equal(r.status, 200)
  assert.deepEqual(r.body, { error: 'not found' })
})

test('unknown routes and methods return 404 no route', async () => {
  const calls = [
    fetch(`${base}/`), fetch(`${base}/nope`), fetch(`${base}/orders`), fetch(`${base}/orders/`),
    fetch(`${base}/orders/1/extra`), fetch(`${base}/orders/1`, { method: 'DELETE' }),
    fetch(`${base}/orders/1`, { method: 'PUT', body: '{}' }),
  ]
  for (const c of calls) {
    const r = await json(await c)
    assert.equal(r.status, 404)
    assert.deepEqual(r.body, { error: 'no route' })
  }
})
